import sys

def main():
    data = sys.stdin.read().split('\n')
    if not data or data[0].strip() == '':
        return
    H, W, k = map(int, data[0].split())
    grid = [list(data[1 + i].rstrip('\n')) for i in range(H)]

    for _ in range(k):
        new = [['.'] * W for _ in range(H)]
        for i in range(H):
            for j in range(W):
                cnt = 0
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                            cnt += 1
                if grid[i][j] == '#':
                    new[i][j] = '#' if cnt in (2, 3) else '.'
                else:
                    new[i][j] = '#' if cnt == 3 else '.'
        grid = new

    sys.stdout.write('\n'.join(''.join(row) for row in grid) + '\n')

main()
